"""Regenerate docs/MODEL_ARSENAL.md from the registries (single source of truth)."""

from __future__ import annotations

from pathlib import Path

from apex_one.compute.registry import load_registry

ROOT = Path(__file__).resolve().parents[1]


def main() -> None:
    reg = load_registry(with_db_overlay=False)
    lines = ["# MODEL ARSENAL", "",
             "_Generated by `python scripts/gen_model_arsenal_doc.py` from `config/model_registry.yaml`, "
             "`config/license_registry.yaml` and `config/design_capability_matrix.yaml`. Do not edit by hand._", "",
             "Reading guide:", "",
             "* **Integration** = code maturity. `IMPLEMENTED` is reserved for engines whose code runs in this "
             "repository's test suite. `CONFIGURED_BUT_UNTESTED` = real client code exists but has never been run "
             "against the real model/provider (only mocked transports). `NOT_YET_SUPPORTED` = registered, invoking "
             "raises `DesignNotSupported` with the reason.",
             "* **Licence** = verified production state. Every external model is `UNKNOWN` (or more restrictive) "
             "until a human records a verification; `reported` is prior knowledge and grants nothing.",
             "* **Routes** = where it could run at $0. Remote routes additionally need a live $0 price check or a "
             "human free-tier attestation before the ZeroCostFirewall allows them.", "",
             "## General / reasoning / coding / multimodal", "",
             "| Model | Integration | Routes | Licence state (verified?) | Reported licence | Notes |",
             "|---|---|---|---|---|---|"]
    for m in reg.models.values():
        if m.category != "general" or m.family in ("mock",):
            continue
        lic = reg.license_for(m)
        routes = ", ".join(sorted({r.provider for r in m.routes})) or "—"
        lines.append(f"| `{m.id}` | {m.integration_status.value} | {routes} | {lic.production_state.value} "
                     f"({'yes' if lic.verified_at else 'no'}) | {lic.reported_license or '—'} | {m.notes or m.description} |")
    lines += ["", "## Design arsenal", "",
              "| System | Group roles | Integration | Adapter | Licence state (verified?) | How to enable |",
              "|---|---|---|---|---|---|"]
    for m in reg.models.values():
        if m.category != "design":
            continue
        lic = reg.license_for(m)
        roles = ", ".join(m.capabilities.design_roles)
        lines.append(f"| `{m.id}` | {roles} | {m.integration_status.value} | {m.adapter} | "
                     f"{lic.production_state.value} ({'yes' if lic.verified_at else 'no'}) | "
                     f"{m.local_hint or m.notes or '—'} |")
    lines += ["", "## Design roles → specialists → native fallback", "", "| Role | Specialists (preference order) | Native |",
              "|---|---|---|"]
    for role, spec in reg.design_matrix["roles"].items():
        lines.append(f"| {role} | {', '.join(spec.get('specialists', []))} | {spec.get('native') or '—'} |")
    lines += ["", "## Page-type design DAGs", "", "| Route | Applies to | Steps |", "|---|---|---|"]
    for name, r in reg.design_matrix["routes"].items():
        lines.append(f"| {name} | {', '.join(r['applies_to'])} | {' → '.join(r['steps'])} |")
    (ROOT / "docs" / "MODEL_ARSENAL.md").write_text("\n".join(lines) + "\n", encoding="utf-8")


if __name__ == "__main__":
    main()
